using System;using System.IO;using System.Collections.Generic;using System.Security.Cryptography;
class QuestOutboxRecoveryFixturesFG {
 static void Check(bool ok,string label){if(!ok)throw new InvalidDataException(label);}
 static string Hash(string path){using(SHA256 h=SHA256.Create())return Convert.ToBase64String(h.ComputeHash(File.ReadAllBytes(path)));}
 static string Payload(Offline70QuestOutboxFG a){string p=a.QuestId+":"+a.GoldCredit+":"+a.GoldDebit+":"+a.ExperienceCredit;foreach(Offline70ItemCountFG d in a.Debits)p+="-"+d.Id+":"+d.Quantity;foreach(Offline70ItemCountFG c in a.Credits)p+="+"+c.Id+":"+c.Quantity;return p;}
 static Offline70EconomyState Deliver(string path,Offline70QuestOutboxFG plan,out bool duplicate){return Offline70Economy.Apply(path,plan.Receipt,"quest-complete",Payload(plan),delegate(Offline70EconomyState s){if(s.Gold<plan.GoldDebit)throw new InvalidDataException("Quest wallet debit");s.Gold=s.Gold-plan.GoldDebit+plan.GoldCredit;s.Experience=Offline70ProgressionFG.AddExperience(s.Experience,plan.ExperienceCredit);s.Level=Offline70ProgressionFG.Level(s.Experience);foreach(Offline70ItemCountFG d in plan.Debits)Offline70Economy.RemoveAssetItem(s,(uint)d.Id,d.Quantity);foreach(Offline70ItemCountFG c in plan.Credits)Offline70Economy.AddAssetItem(s,(uint)c.Id,c.Quantity);if(!s.CompletedQuests.Contains(plan.QuestId))s.CompletedQuests.Add(plan.QuestId);},out duplicate);}
 static void InitializeEconomy(string path,uint xp){Offline70Economy.Initialize(path,169,false);bool duplicate;Offline70Economy.Apply(path,"fixture-seed-xp","diagnostic-seed",xp.ToString(),delegate(Offline70EconomyState state){state.Experience=xp;state.Level=Offline70ProgressionFG.Level(xp);},out duplicate);}
 static Offline70ProgressionStateFG SeedQuest(string path,Offline70QuestEngineFG engine){return SeedQuest(path,engine,396);}
 static Offline70ProgressionStateFG SeedQuest(string path,Offline70QuestEngineFG engine,uint experience){Offline70ProgressionStateFG s=new Offline70ProgressionStateFG{Gold=169,Experience=experience};s.Completed.Add(101);Offline70QuestEngineFG.Seed(path,s);s=engine.Accept(path,102);s=engine.Clear(path,1,0,"lorien-clear");return engine.Complete(path,102,1,ushort.MaxValue,Offline70QuestEngineFG.CompletionReceipt(s,102));}
 static int Main(string[] args){try{if(args.Length!=3)return 2;if(Directory.Exists(args[2]))throw new IOException("Fresh recovery fixture directory required");Directory.CreateDirectory(args[2]);Offline70QuestCatalogFG catalog=Offline70QuestCatalogFG.Load(args[0]);Offline70ItemMetadataFG.Register(args[1]);Offline70QuestEngineFG engine=new Offline70QuestEngineFG(catalog);string quest=Path.Combine(args[2],"quest.xml"),economy=Path.Combine(args[2],"economy.xml");InitializeEconomy(economy,396);Offline70ProgressionStateFG s=SeedQuest(quest,engine);Offline70QuestOutboxFG plan=Offline70QuestEngineFG.Load(quest).Outbox[0];Check(!plan.Delivered&&Offline70Economy.Load(economy).Gold==169,"crash before economy commit keeps pending outbox");bool duplicate;Offline70EconomyState assets=Deliver(economy,plan,out duplicate);Check(!duplicate&&assets.Gold==320&&assets.Experience==864&&assets.Level==1&&assets.Inventory.Count==1&&!Offline70QuestEngineFG.Load(quest).Outbox[0].Delivered,"crash after economy commit before checkpoint");string before=Hash(economy);assets=Deliver(economy,Offline70QuestEngineFG.Load(quest).Outbox[0],out duplicate);Check(duplicate&&Hash(economy)==before&&assets.Gold==320&&assets.Experience==864&&assets.Level==1&&assets.Inventory.Count==1,"retry after economy commit cannot duplicate assets");s=Offline70QuestEngineFG.MarkDelivered(quest,plan.Receipt);Check(s.Outbox[0].Delivered,"delivery checkpoint restart");
  string fullQuest=Path.Combine(args[2],"full-quest.xml"),fullEconomy=Path.Combine(args[2],"full-economy.xml");InitializeEconomy(fullEconomy,396);Offline70Economy.Apply(fullEconomy,"fill-main-equipment","diagnostic-fill","16400x32",delegate(Offline70EconomyState state){Offline70Economy.AddAssetItem(state,16400,32);},out duplicate);s=SeedQuest(fullQuest,engine);plan=s.Outbox[0];before=Hash(fullEconomy);bool rejected=false;try{Deliver(fullEconomy,plan,out duplicate);}catch(InvalidDataException){rejected=true;}Check(rejected&&Hash(fullEconomy)==before&&!Offline70QuestEngineFG.Load(fullQuest).Outbox[0].Delivered,"full bag leaves both wallet and outbox retryable");Offline70Economy.Apply(fullEconomy,"free-one-slot","diagnostic-delete","16400x1",delegate(Offline70EconomyState state){Offline70Economy.RemoveAssetItem(state,16400,1);},out duplicate);assets=Deliver(fullEconomy,Offline70QuestEngineFG.Load(fullQuest).Outbox[0],out duplicate);Check(!duplicate&&assets.Gold==320&&assets.Experience==864&&assets.Level==1&&assets.Inventory.Count==32,"pending completed quest rewards deliver after space is available");Offline70QuestEngineFG.MarkDelivered(fullQuest,plan.Receipt);
  string crossQuest=Path.Combine(args[2],"cross-quest.xml"),crossEconomy=Path.Combine(args[2],"cross-economy.xml");InitializeEconomy(crossEconomy,990);s=SeedQuest(crossQuest,engine,990);plan=s.Outbox[0];Check(s.Experience==990&&plan.ExperienceCredit==468,"quest projection XP remains authoritative until economy commit");assets=Deliver(crossEconomy,plan,out duplicate);Check(!duplicate&&assets.Experience==1458&&assets.Level==2&&assets.Gold==320,"gold item XP and crossing level committed atomically");before=Hash(crossEconomy);assets=Deliver(crossEconomy,plan,out duplicate);Check(duplicate&&Hash(crossEconomy)==before&&assets.Experience==1458&&assets.Level==2,"crash replay never duplicates quest XP or level");Offline70QuestEngineFG.MarkDelivered(crossQuest,plan.Receipt);
  string legacyQuest=Path.Combine(args[2],"legacy101-quest.xml"),legacyEconomy=Path.Combine(args[2],"legacy101-economy.xml");Offline70ProgressionStateFG legacy=new Offline70ProgressionStateFG{Gold=100,Experience=396};legacy.Completed.Add(101);Offline70QuestEngineFG.Seed(legacyQuest,legacy);Offline70Economy.Initialize(legacyEconomy,100,false);Offline70Economy.Apply(legacyEconomy,"legacy101-seed-xp","diagnostic-seed","396",delegate(Offline70EconomyState state){state.Experience=396;state.Level=1;state.CompletedQuests.Add(101);},out duplicate);before=Hash(legacyQuest);string legacyBefore=Hash(legacyEconomy);bool legacyRejected=false;try{engine.Complete(legacyQuest,101,1,ushort.MaxValue,Offline70QuestEngineFG.CompletionReceipt(Offline70QuestEngineFG.Load(legacyQuest),101));}catch(InvalidDataException){legacyRejected=true;}s=Offline70QuestEngineFG.SyncAssets(legacyQuest,100,396,new List<Offline70ItemCountFG>());Check(legacyRejected&&Hash(legacyQuest)==before&&Hash(legacyEconomy)==legacyBefore&&s.Gold==100&&s.Experience==396&&s.Outbox.Count==0,"old completed101 remains gold100 XP396; no retroactive recalculation or outbox");
  File.WriteAllText(Path.Combine(args[2],"report.json"),"{\"allPassed\":true,\"crashBeforeEconomy\":true,\"crashBeforeCheckpoint\":true,\"noDoubleRewards\":true,\"fullBagAtomicFailure\":true,\"pendingRewardRetry\":true,\"experienceAtomic\":true,\"levelCrossing\":true,\"legacyCompletedQuestUnchanged\":true}");Console.WriteLine("PASS quest outbox/economy two-store crash recovery, no repeated reward, full bag atomic failure and successful retry");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
